with enriched as (select *, sum(temp_c) over w_grp as running_sum_temp_c, max(temp_c) over w_grp as running_max_temp_c, count(temp_c) over w_grp as running_count_temp_c, round(temp_c / sum(temp_c) over (partition by device_code), 4) as temp_c_share from device_readings window w_grp as (partition by device_code order by humidity, id rows between unbounded preceding and current row)) select date_trunc('hour', reading_ts) as hour_window, sort_array(collect_set(device_code)) as device_code_list, (unix_timestamp(max(reading_ts)) - unix_timestamp(min(reading_ts))) / 60 as duration_min, round(sum(running_max_temp_c) / nullif(count(case when device_code = 'DV-03' then 1 end), 0), 2) as running_max_temp_c_per_dv_03 from enriched group by date_trunc('hour', reading_ts) order by hour_window;
